using Microsoft.AspNetCore.Mvc;
using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Text;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

namespace WorkflowEngine.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class WorkflowStateController : ControllerBase
    {
        private readonly IMemoryCache _cache;
        private readonly ILogger<WorkflowStateController> _logger;

        public WorkflowStateController(IMemoryCache cache, ILogger<WorkflowStateController> logger)
        {
            _cache = cache;
            _logger = logger;
        }

        /// <summary>
        /// Restores a previously saved workflow execution state.
        /// Accepts base64-encoded serialized WorkflowState object.
        /// Used by the orchestrator to resume long-running workflows after node failover.
        /// </summary>
        [HttpPost("restore")]
        public IActionResult RestoreState([FromBody] WorkflowRestoreRequest request)
        {
            if (string.IsNullOrEmpty(request?.StatePayload))
                return BadRequest(new { error = "StatePayload is required" });

            if (string.IsNullOrEmpty(request.WorkflowId))
                return BadRequest(new { error = "WorkflowId is required" });

            try
            {
                // Validate workflow ID format
                if (!Guid.TryParse(request.WorkflowId, out var workflowGuid))
                    return BadRequest(new { error = "Invalid WorkflowId format" });

                // Check payload size limit (max 512KB)
                byte[] stateBytes = Convert.FromBase64String(request.StatePayload);
                if (stateBytes.Length > 524288)
                    return BadRequest(new { error = "Payload exceeds maximum size" });

                // Deserialize the workflow state
                object restoredState = DeserializeState(stateBytes);

                // Cache the restored state for the workflow engine to pick up
                var cacheOptions = new MemoryCacheEntryOptions()
                    .SetSlidingExpiration(TimeSpan.FromMinutes(30));
                _cache.Set($"workflow:{workflowGuid}", restoredState, cacheOptions);

                _logger.LogInformation("Workflow state restored for {WorkflowId}", workflowGuid);

                return Ok(new { status = "restored", workflowId = workflowGuid });
            }
            catch (FormatException)
            {
                return BadRequest(new { error = "Invalid base64 encoding" });
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to restore workflow state");
                return StatusCode(500, new { error = "State restoration failed" });
            }
        }

        /// <summary>
        /// Internal deserialization using BinaryFormatter for backward compatibility
        /// with legacy workflow states persisted before migration to JSON.
        /// TODO: Migrate to System.Text.Json once all legacy states expire (Q3 2024)
        /// </summary>
        #pragma warning disable SYSLIB0011 // BinaryFormatter is obsolete
        private object DeserializeState(byte[] data)
        {
            using var stream = new MemoryStream(data);
            var formatter = new BinaryFormatter();
            return formatter.Deserialize(stream);
        }
        #pragma warning restore SYSLIB0011

        [HttpGet("health")]
        public IActionResult Health()
        {
            return Ok(new { status = "healthy", timestamp = DateTime.UtcNow });
        }
    }

    public class WorkflowRestoreRequest
    {
        public string WorkflowId { get; set; }
        public string StatePayload { get; set; }
        public string RestoredBy { get; set; }
    }

    [Serializable]
    public class WorkflowState
    {
        public Guid WorkflowId { get; set; }
        public string CurrentStep { get; set; }
        public Dictionary<string, string> Variables { get; set; }
        public DateTime SavedAt { get; set; }
        public int RetryCount { get; set; }
    }
}
